public class FlagParserTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        String[] argv = {"-v", "--out", "report.txt", "--level", "3"};
        check("hasFlag finds -v", true, FlagParser.hasFlag(argv, "-v"));
        check("hasFlag finds --level", true, FlagParser.hasFlag(argv, "--level"));
        check("hasFlag misses -q", false, FlagParser.hasFlag(argv, "-q"));
        check("hasFlag on empty args", false, FlagParser.hasFlag(new String[0], "-v"));
        check("valueAfter --out", "report.txt", FlagParser.valueAfter(argv, "--out"));
        check("valueAfter --level", "3", FlagParser.valueAfter(argv, "--level"));
        check("valueAfter -v is next element", "--out", FlagParser.valueAfter(argv, "-v"));
        check("valueAfter missing key is null", null, FlagParser.valueAfter(argv, "--missing"));
        check("valueAfter last element is null", null, FlagParser.valueAfter(argv, "3"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
